/*Marathon Open Source Saved Game Editor (MOSSGE)Started 04/19/2000Version 0.8d released 04/19/2000Version 1.0 released 04/20/2000Version 1.1 released 04/23/2000Version 1.2 released 04/25/2000Version 1.2.1 released 05/13/2000Version 1.2.5 released 05/29/2000By Craig Miller <jedric@geocities.com>Navigation Services code taken from Apple examples*/#define BUILD_CLASSIC	1#define BUILD_CARBON	2//#define BUILD_TYPE		BUILD_CLASSIC#define BUILD_TYPE		BUILD_CARBON#if BUILD_TYPE == BUILD_CARBON#define TARGET_API_MAC_CARBON 1#endif#define NIL				0#define NUM_OF_WEAPONS	35#define PLAYER_STATS	2#define MARATHON_2		1#define MARATHON_I		2#include <Files.h>#include <Dialogs.h>#include <Navigation.h>#include <Types.h>#include <TextUtils.h>typedef struct {	short items[80];} SavedData;// Prototypesvoid TBInit(void);long findDataLocation(char *buffer, long bsize);Boolean editSavedGame(SavedData *savedData, short marathonVers);NavTypeListHandle MakeTypeList(OSType applSignature, int numTypes, OSType *types);OSType GetApplSignature();FSSpec GetFSSpecWithNav(Boolean *cancel);int PStrToNum(Str255 pStr);void IntToPStr(int num, Str255 pStr);void IntToASCII(int n, char s[]);void Reverse(char s[]);int main(void){	short frnum;	long theEOF, writeCount=sizeof(SavedData), dataLoc;	char *buffer;	SavedData savedData;	Boolean cancel;	FSSpec theFSS;	short maraVers;	FInfo fileInfo;		TBInit();		theFSS=GetFSSpecWithNav(&cancel);	if (cancel) return 0;		FSpOpenDF(&theFSS, fsRdWrPerm, &frnum);		// Get Marathon version	FSpGetFInfo(&theFSS, &fileInfo);	if (fileInfo.fdType=='sga2') maraVers=MARATHON_2;	if (fileInfo.fdType=='sga∞') maraVers=MARATHON_I;		GetEOF(frnum, &theEOF);		buffer=NewPtr(theEOF);		if (FSRead(frnum, &theEOF, buffer)!=0) return 0;		dataLoc=findDataLocation(buffer, theEOF); // find the player info	dataLoc+=77; // go to the start of items		BlockMove(buffer+dataLoc, &savedData, sizeof(SavedData)); // copy the required data to savedData		DisposePtr(buffer);		if (SetFPos(frnum, 1, dataLoc)==0) {		if (editSavedGame(&savedData, maraVers)) FSWrite(frnum, &writeCount, &savedData);	}		FSClose(frnum);	return 0;}void TBInit(void){	#if BUILD_TYPE == BUILD_CLASSIC	InitFonts();	InitMenus();	InitWindows();	InitDialogs(NIL);	TEInit();	#endif	InitCursor();	#if BUILD_TYPE == BUILD_CLASSIC	MoreMasters();	MoreMasters();	MoreMasters();	MoreMasters();	MaxApplZone();	#endif}long findDataLocation(char *buffer, long bsize) // find location of 'plyr'{	long lpcnt;		bsize-=4;		for (lpcnt=0; lpcnt<bsize; lpcnt++) {		if (buffer[lpcnt]=='p') {			lpcnt++;			if (buffer[lpcnt]=='l') {				lpcnt++;				if (buffer[lpcnt]=='y') {					lpcnt++;					if (buffer[lpcnt]=='r') {						return lpcnt;					}				}			}		}	}		return -1;}Boolean editSavedGame(SavedData *savedData, short marathonVers) // The Mac interface stuff{	short itemHit, kind;	long itemNum;	int lpcnt;	DialogPtr editDialog;	Handle item[NUM_OF_WEAPONS+PLAYER_STATS];	Str255 itemStr, maxStr="\p32767";        Rect theR;		editDialog=GetNewDialog(128, NULL, (WindowPtr) -1);	SetDialogDefaultItem(editDialog, 1);	SetDialogCancelItem(editDialog, 2);	DrawDialog(editDialog);		// Weapons	for (lpcnt=0; lpcnt<NUM_OF_WEAPONS; lpcnt++) {		GetDialogItem(editDialog, (2*lpcnt)+5, &kind, &item[lpcnt], &theR);		NumToString((*savedData).items[lpcnt+16], itemStr);		SetDialogItemText(item[lpcnt], itemStr);	}		// Health	for (lpcnt=NUM_OF_WEAPONS; lpcnt<NUM_OF_WEAPONS+PLAYER_STATS; lpcnt++) {		GetDialogItem(editDialog, (2*lpcnt)+5, &kind, &item[lpcnt], &theR);		NumToString((*savedData).items[lpcnt-NUM_OF_WEAPONS], itemStr);		SetDialogItemText(item[lpcnt], itemStr);	}		// Hide non-m2 items	if (marathonVers==MARATHON_2) for (lpcnt=70; lpcnt<74; lpcnt++) HideDialogItem(editDialog, lpcnt);		do {		ModalDialog(NIL, &itemHit);				if (itemHit==78) {			if (marathonVers==MARATHON_2) {				for (lpcnt=0; lpcnt<NUM_OF_WEAPONS+PLAYER_STATS; lpcnt++) {					if (lpcnt !=33 & lpcnt !=34) SetDialogItemText(item[lpcnt], maxStr);				}			}			if (marathonVers==MARATHON_I) for (lpcnt=0; lpcnt<NUM_OF_WEAPONS+PLAYER_STATS; lpcnt++) SetDialogItemText(item[lpcnt], maxStr);		}			} while (itemHit!=1 & itemHit!=2);		// Weapons	for (lpcnt=0; lpcnt<NUM_OF_WEAPONS; lpcnt++) {		GetDialogItemText(item[lpcnt], itemStr);		StringToNum(itemStr, &itemNum);		(*savedData).items[lpcnt+16]=(short)itemNum;	}		// Health	for (lpcnt=NUM_OF_WEAPONS; lpcnt<NUM_OF_WEAPONS+PLAYER_STATS; lpcnt++) {		GetDialogItemText(item[lpcnt], itemStr);		StringToNum(itemStr, &itemNum);		savedData[0].items[lpcnt-NUM_OF_WEAPONS]=(short)itemNum;	}		DisposeDialog(editDialog);		if (itemHit==1) return true;	if (itemHit==2) return false;		return false;}NavTypeListHandle MakeTypeList(OSType applSignature, int numTypes, OSType *types){	int i;	NavTypeListHandle h = (NavTypeListHandle) NewHandleClear ( sizeof (NavTypeList) + 																(sizeof (OSType) * (numTypes-1)) );	if ( h != nil )	{		(*h)->componentSignature = (applSignature == 0L) ? 									GetApplSignature() : applSignature;		(*h)->reserved = 0;		(*h)->osTypeCount = numTypes;		for (i = 0; i < numTypes; i++ )		{			(*h)->osType[i] = types[i];		}	}	return h;}OSType GetApplSignature(){	ProcessSerialNumber	PSN;	ProcessInfoRec		info;	Str31				processName;	FSSpec				FileSpec;	info.processInfoLength = sizeof ( ProcessInfoRec );	 						info.processName = processName;	info.processAppSpec = &FileSpec;	GetCurrentProcess(&PSN);	GetProcessInformation(&PSN, &info);	return info.processSignature;}FSSpec GetFSSpecWithNav(Boolean *cancel){		NavReplyRecord		theReply;	NavDialogOptions	dialogOptions;	OSErr				theErr = noErr;	NavTypeListHandle	openList = NULL;	OSType *types;	NavTypeListHandle fType;	FSSpec		finalFSSpec;		AEKeyword 	keyWord;	DescType 	typeCode;	Size 		actualSize = 0;		types=(OSType *)NewPtr(sizeof(types)*2);	types[0]='sga∞';	types[1]='sga2';	fType=MakeTypeList('????', 2, types);	DisposePtr((char *)types);		// use the default location for the dialog:	theErr = NavGetDefaultDialogOptions( &dialogOptions );			openList = fType;			theErr = NavChooseFile(NULL, &theReply, &dialogOptions, NULL, NULL, NULL, openList, NULL);		if ( theReply.validRecord && theErr == noErr )	{		// grab the target FSSpec from the AEDesc:				// retrieve the returned selection:		// there is only one selection here we get only the first AEDescList:		if (( theErr = AEGetNthPtr( &(theReply.selection), 1, typeFSS, &keyWord, &typeCode, &finalFSSpec, sizeof( FSSpec ), &actualSize )) == noErr )		{			// 'finalFSSpec' is the chosen file…		}				theErr = NavDisposeReply( &theReply );				*cancel=false;	} else {		*cancel=true;	}		if ( openList != NULL )		DisposeHandle( (Handle)openList );			return finalFSSpec;}